<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();
$metrics=['services'=>(int)query('SELECT COUNT(*) FROM services WHERE is_active=1')->fetchColumn(),'patients'=>(int)query("SELECT COUNT(*) FROM users WHERE role='patient' AND is_active=1")->fetchColumn(),'requests'=>(int)query('SELECT COUNT(*) FROM appointment_requests')->fetchColumn(),'pending'=>(int)query("SELECT COUNT(*) FROM appointment_requests WHERE status='requested'")->fetchColumn()];
$recent=query('SELECT a.*,TIME_FORMAT(a.preferred_time,"%H:%i") AS time_label FROM appointment_requests a ORDER BY a.created_at DESC,a.id DESC LIMIT 5')->fetchAll();
$mix=query('SELECT c.name,COUNT(s.id) AS total FROM categories c LEFT JOIN services s ON s.category_id=c.id AND s.is_active=1 GROUP BY c.id,c.name ORDER BY c.id')->fetchAll();
$activity=query('SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 4')->fetchAll();
$pageTitle='Clinic overview | Wellnest Workspace';$adminPageLabel='Overview';require __DIR__.'/../components/admin_header.php';
?>
<div class="admin-page-heading"><div><span class="admin-eyebrow">A LITTLE CLARITY FOR YOUR DAY</span><h1>Clinic overview<span>.</span></h1><p>Your care services, people, and visit requests — all together.</p></div><div class="heading-actions"><span class="admin-today"><?=icon('calendar')?> <?=e(date('d M Y'))?></span><a class="btn btn-primary" href="<?=e(base_url('admin/service_form.php'))?>"><?=icon('plus')?> Add service</a></div></div>
<section class="stats-grid" aria-label="Clinic statistics"><?php foreach([['heart','Active services',$metrics['services'],'Available on the website','mint'],['users','Patient accounts',$metrics['patients'],'Registered and active','peach'],['calendar','Visit requests',$metrics['requests'],'All demo requests','blue'],['clock','Awaiting review',$metrics['pending'],'Requests to follow up','lavender']] as [$symbol,$label,$value,$caption,$color]): ?><article class="stat-card"><div class="stat-card-top"><span><?=e($label)?></span><span class="metric-icon <?=$color?>"><?=icon($symbol)?></span></div><strong><?=$value?></strong><p><?=e($caption)?></p></article><?php endforeach; ?></section>
<div class="overview-grid"><section class="admin-panel requests-panel"><div class="panel-heading"><div><h2>Recent visit requests</h2><p>A closer look at the latest activity.</p></div><a class="panel-link" href="<?=e(base_url('admin/appointments.php'))?>">View all <?=icon('arrow')?></a></div><div class="admin-table-wrap"><table class="admin-table overview-table"><thead><tr><th>Patient & service</th><th>Preferred visit</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $request): ?><tr><td><div class="table-person"><span class="person-avatar"><?=e(initials($request['full_name']))?></span><div><strong><?=e($request['full_name'])?></strong><small><?=e($request['service_name'])?></small></div></div></td><td><strong><?=e(date('d M Y',strtotime($request['preferred_date'])))?></strong><small><?=e($request['time_label'])?> · GMT+7</small></td><td><span class="status-badge status-<?=e($request['status'])?>"><?=e(ucfirst($request['status']))?></span></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="3" class="table-empty">New visit requests will appear here.</td></tr><?php endif; ?></tbody></table></div><div class="panel-footnote"><?=icon('shield')?> Demo requests only. No clinical appointments are booked.</div></section><aside class="care-mix admin-panel"><div class="panel-heading"><div><h2>Your care mix</h2><p>Published services by category.</p></div><span class="mini-icon"><?=icon('heart')?></span></div><div class="mix-total"><strong><?=$metrics['services']?></strong><span>services to explore</span></div><?php foreach($mix as $index=>$category): ?><div class="mix-item"><div><span><i class="mix-dot mix-<?=$index?>"></i><?=e($category['name'])?></span><strong><?=(int)$category['total']?></strong></div><div class="mix-track"><span class="mix-<?=$index?>" style="width:<?=$metrics['services']?round((int)$category['total']/$metrics['services']*100):0?>%"></span></div></div><?php endforeach; ?><a class="panel-link" href="<?=e(base_url('admin/services.php'))?>">Manage your services <?=icon('arrow')?></a></aside><section class="admin-panel activity-panel"><div class="panel-heading"><div><h2>Workspace activity</h2><p>Changes made with care.</p></div><span class="soft-badge">AUDIT TRAIL</span></div><div class="activity-list"><?php foreach($activity as $entry): ?><article><span class="activity-icon"><?=icon($entry['entity']==='service'?'heart':'calendar')?></span><div><strong><?=e($entry['description'])?></strong><p><?=e($entry['full_name']??'System')?> <span>·</span> <?=e(date('d M, H:i',strtotime($entry['created_at'])))?></p></div></article><?php endforeach; ?></div></section><aside class="admin-care-note"><span><?=icon('plus')?></span><span class="admin-eyebrow">SMALL DETAILS. BETTER CARE.</span><h2>Keep your care<br>information current.</h2><p>Clear descriptions and up-to-date fees help patients choose their next step.</p><a href="<?=e(base_url('admin/services.php'))?>">Review services <?=icon('arrow-up')?></a><b aria-hidden="true">✳</b></aside></div>
